INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('amethyst', 1, 'published', 'pods', 'Amethyst', '#7A2DB8', '{"bg":"#1E0A2E","bg2":"#0B0414","surface":"#6A1FA8","accent":"#C58BFF","glow":"#9B3DEB"}', 'assets/img/amethyst.webp?v=2', 'assets/img/amethyst-atmo.webp', '[{"src":"assets/img/amethyst-photos-2.webp","cap":{"uz":"Asl suratlar: old, orqa va yon tomondan","ru":"Оригинальные фото: спереди, сзади и сбоку","en":"Original photos: front, back and side","ar":"صور أصلية: من الأمام والخلف والجانب"}},{"src":"assets/img/amethyst-photos-1.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/amethyst-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/amethyst-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/amethyst-scent.webp","cap":{"uz":"Ametist va lavanda — chuqur, iliq ifor","ru":"Аметист и лаванда — глубокий, тёплый аромат","en":"Amethyst and lavender — deep and warm","ar":"الجمشت واللافندر — عطر عميق ودافئ"}}]', '{"uz":{"scent":"Ametist va lavanda","line":"Kiyimingizdan kun bo‘yi ketmaydigan ifor","hook":"Kechki ko‘ylak ham ertalabgidek xushbo‘y.","desc":"Amethyst — BÄRC’ning eng chuqur va iliq ifori. U kiyimni ochganingizda emas, kun bo‘yi o‘zini eslatib turadi. Qiyin dog‘ va hidlarga qarshi kuchli, sovuq suvda va qisqa dasturda ham ishlaydi.","for":"Iforni yaqindan sezishni yaxshi ko‘radiganlar uchun: sevimli sviterlar, kechki uchrashuvlar, mehmon kutayotgan uy."},"ru":{"scent":"Аметист и лаванда","line":"Аромат, который остаётся с вами весь день","hook":"Вечером рубашка пахнет так же, как утром.","desc":"Amethyst — самый глубокий и тёплый аромат BÄRC. Он напоминает о себе не только когда вы открываете шкаф, а весь день. Сильный против сложных пятен и запахов, работает в холодной воде и в короткой программе.","for":"Для тех, кто любит чувствовать аромат близко: любимые свитера, вечерние встречи, дом в ожидании гостей."},"en":{"scent":"Amethyst and lavender","line":"A scent that stays with you all day","hook":"Your evening shirt smells like it did this morning.","desc":"Amethyst is BÄRC’s deepest, warmest scent. It doesn’t only greet you when you open the wardrobe — it stays with you all day. Strong on tough stains and odours, and it works in cold water and on short cycles.","for":"For those who love a scent up close: favourite sweaters, evening plans, a home expecting guests."},"ar":{"scent":"الجمشت واللافندر","line":"عطر يرافقك طوال اليوم","hook":"قميص المساء بعطر الصباح نفسه.","desc":"Amethyst هو أعمق عطور BÄRC وأدفؤها. لا يحيّيك فقط عند فتح الخزانة، بل يبقى معك طوال اليوم. قوي ضد البقع والروائح الصعبة، ويعمل في الماء البارد وفي البرامج القصيرة.","for":"لمن يحب أن يشعر بالعطر عن قرب: الكنزات المفضلة، سهرات المساء، بيت ينتظر الضيوف."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('crystal', 2, 'published', 'pods', 'Crystal Bloom', '#1F5FD9', '{"bg":"#071A45","bg2":"#030A1E","surface":"#1C55D6","accent":"#7DC2FF","glow":"#2F7BFF"}', 'assets/img/crystal.webp?v=2', 'assets/img/crystal-atmo.webp', '[{"src":"assets/img/crystal-photos.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/crystal-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/crystal-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/crystal-scent.webp","cap":{"uz":"Gul barglaridek tiniq ifor","ru":"Прозрачный, как лепестки","en":"Clear as petals","ar":"صافٍ كبتلات الزهور"}}]', '{"uz":{"scent":"Gul barglari","line":"Yangi uzilgan gullardek yengil va tiniq","hook":"Shkafni ochasiz — gulzor.","desc":"Crystal Bloom — yengil, tiniq, gulli ifor. Og‘ir emas, bosmaydi — shunchaki “toza” degan his qoldiradi. Dog‘ va hidni ketkazadi, ranglarni yorqin saqlaydi, sovuq suvda ham to‘liq eriydi.","for":"Yengillikni sevadiganlar uchun: kundalik ko‘ylaklar, rangli kiyimlar, yozgi yengil matolar."},"ru":{"scent":"Цветочные лепестки","line":"Лёгкий и прозрачный, как свежие цветы","hook":"Открываете шкаф — а там цветы.","desc":"Crystal Bloom — лёгкий, прозрачный, цветочный. Не тяжёлый и не навязчивый — просто ощущение «чисто». Удаляет пятна и запахи, сохраняет яркость цветов, полностью растворяется даже в холодной воде.","for":"Для тех, кто любит лёгкость: повседневные рубашки, цветные вещи, летние ткани."},"en":{"scent":"Flower petals","line":"Light and clear, like fresh-cut flowers","hook":"Open the wardrobe — find a garden.","desc":"Crystal Bloom is light, clear and floral. Never heavy, never too much — just the feeling of “clean”. It removes stains and odours, keeps colours bright and fully dissolves even in cold water.","for":"For lovers of lightness: everyday shirts, colourful clothes, light summer fabrics."},"ar":{"scent":"بتلات الزهور","line":"خفيف وصافٍ كالزهور المقطوفة للتو","hook":"تفتح الخزانة — فتجد حديقة.","desc":"Crystal Bloom عطر خفيف وصافٍ وزهري. ليس ثقيلًا ولا طاغيًا — مجرد إحساس بالنظافة. يزيل البقع والروائح، ويحافظ على إشراق الألوان، ويذوب تمامًا حتى في الماء البارد.","for":"لمحبي الخفة: القمصان اليومية، الملابس الملونة، أقمشة الصيف الخفيفة."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('original', 3, 'published', 'pods', 'Original', '#23963F', '{"bg":"#062A1A","bg2":"#02130B","surface":"#1E8A3E","accent":"#8EE58A","glow":"#2FBF55"}', 'assets/img/original.webp?v=2', 'assets/img/original-atmo.webp', '[{"src":"assets/img/original-photos.webp","cap":{"uz":"Asl suratlar: old, burchakdan, orqa, yon va yaqin plan","ru":"Оригинальные фото: спереди, сбоку, сзади и крупным планом","en":"Original photos: front, angle, back, side and close-ups","ar":"صور أصلية: من الأمام والجانب والخلف وعن قرب"}},{"src":"assets/img/original-studio.webp","cap":{"uz":"Har bir qadoqda — 60 ta yuvish","ru":"В каждой упаковке — 60 стирок","en":"60 washes in every pack","ar":"60 غسلة في كل عبوة"}},{"src":"assets/img/original-room.webp","cap":{"uz":"Kir yuvish xonangizda doim qo‘l ostida","ru":"Всегда под рукой в вашей прачечной","en":"Always at hand in your laundry room","ar":"دائمًا في متناول يدك في غرفة الغسيل"}},{"src":"assets/img/original-scent.webp","cap":{"uz":"Shudringli yaproqlar tetikligi","ru":"Свежесть листьев в росе","en":"The freshness of dewy leaves","ar":"انتعاش الأوراق المغطاة بالندى"}}]', '{"uz":{"scent":"Yashil yaproqlar","line":"Yomg‘irdan keyingi bog‘dek tetik","hook":"Toza kirning eng to‘g‘ri hidi.","desc":"Original — BÄRC’ning klassik formulasi. Shudringli yaproqlardek tetik ifor va qiyin dog‘larga kuchli ta’sir. Bir marta sinab ko‘rgach, “toza” deganda shu hidni eslaysiz.","for":"Klassikani tanlaydiganlar uchun: oilaviy katta yuvishlar, choyshab va sochiqlar, har kungi kiyim."},"ru":{"scent":"Зелёные листья","line":"Свежий, как сад после дождя","hook":"Тот самый запах чистого белья.","desc":"Original — классическая формула BÄRC. Свежий аромат листьев в росе и сильное действие против сложных пятен. Попробовав раз, вы будете вспоминать именно этот запах, когда слышите слово «чисто».","for":"Для тех, кто выбирает классику: большие семейные стирки, постельное бельё и полотенца, одежда на каждый день."},"en":{"scent":"Green leaves","line":"Fresh as a garden after rain","hook":"The way clean laundry should smell.","desc":"Original is BÄRC’s classic formula: the fresh scent of dewy leaves and strong action on tough stains. Try it once, and this is the smell you’ll think of when someone says “clean”.","for":"For those who choose the classic: big family washes, bed linen and towels, everyday clothes."},"ar":{"scent":"أوراق خضراء","line":"منعش كحديقة بعد المطر","hook":"الرائحة الحقيقية للغسيل النظيف.","desc":"Original هي التركيبة الكلاسيكية من BÄRC: عطر منعش كأوراق يغطيها الندى، وفعالية قوية ضد البقع الصعبة. جرّبها مرة، وستتذكر هذه الرائحة كلما سمعت كلمة «نظيف».","for":"لمن يختار الكلاسيكية: غسلات العائلة الكبيرة، الشراشف والمناشف، ملابس كل يوم."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-amethyst', 4, 'published', 'gel', 'Amethyst', '#6B2FC0', '{"bg":"#1B0B30","bg2":"#090312","surface":"#5B21A8","accent":"#B98CFF","glow":"#8A3FF0"}', 'assets/img/gel-amethyst.webp?v=2', 'assets/img/gel-amethyst-atmo.webp', '[{"src":"assets/img/gel-amethyst-studio.webp","cap":{"uz":"Har tomchida — toza natija","ru":"Чистый результат в каждой капле","en":"A clean result in every drop","ar":"نتيجة نظيفة في كل قطرة"}},{"src":"assets/img/gel-room.webp","cap":{"uz":"Uchala ifor — bitta oila","ru":"Три аромата — одна семья","en":"Three scents, one family","ar":"ثلاثة عطور — عائلة واحدة"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Asl dizayn: 1000 ml, 22 yuvish","ru":"Оригинальный дизайн: 1000 мл, 22 стирки","en":"Original design: 1000 ml, 22 washes","ar":"التصميم الأصلي: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Ametist va lavanda","line":"Iliq va chuqur ifor — endi gelda","hook":"Sevimli ifor — endi har tomchida.","desc":"BÄRC Gel Amethyst — kapsuladagi sevimli iforning suyuq gel shakli. Tolaga chuqur singib, qiyin dog‘ va hidni ketkazadi, kiyimga iliq va chuqur ifor beradi. Sovuq va qisqa dasturda ham ishlaydi.","for":"Dozani o‘zi tanlashni yoqtiradiganlar uchun: kichik yuklar, nozik kiyimlar, tez-tez yuvish."},"ru":{"scent":"Аметист и лаванда","line":"Тёплый глубокий аромат — теперь в геле","hook":"Любимый аромат — в каждой капле.","desc":"BÄRC Gel Amethyst — любимый аромат капсул в форме жидкого геля. Глубоко проникает в волокна, убирает сложные пятна и запахи и дарит одежде тёплый глубокий аромат. Работает и в холодной короткой стирке.","for":"Для тех, кто любит дозировать сам: небольшие загрузки, деликатные вещи, частые стирки."},"en":{"scent":"Amethyst and lavender","line":"A warm, deep scent — now as a gel","hook":"Your favourite scent, in every drop.","desc":"BÄRC Gel Amethyst is our favourite pod scent as a liquid gel. It goes deep into fibres, lifts tough stains and odours and leaves a warm, deep scent. Works in cold, short washes too.","for":"For people who like to dose themselves: small loads, delicate clothes, frequent washes."},"ar":{"scent":"الجمشت والخزامى","line":"عطر دافئ وعميق — الآن جل","hook":"عطرك المفضل في كل قطرة.","desc":"BÄRC Gel Amethyst هو عطر الكبسولات المفضل على شكل جل سائل. يتغلغل في الألياف، ويزيل البقع والروائح الصعبة، ويترك عطرًا دافئًا عميقًا. يعمل في الغسيل البارد والقصير أيضًا.","for":"لمن يحب أن يحدد الكمية بنفسه: حمولات صغيرة، ملابس رقيقة، غسيل متكرر."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-crystal', 5, 'published', 'gel', 'Crystal Bloom', '#1F55D0', '{"bg":"#06173F","bg2":"#020818","surface":"#1846C0","accent":"#79B8FF","glow":"#2A6CF0"}', 'assets/img/gel-crystal.webp?v=2', 'assets/img/gel-crystal-atmo.webp', '[{"src":"assets/img/gel-crystal-studio.webp","cap":{"uz":"Har tomchida — toza natija","ru":"Чистый результат в каждой капле","en":"A clean result in every drop","ar":"نتيجة نظيفة في كل قطرة"}},{"src":"assets/img/gel-room.webp","cap":{"uz":"Uchala ifor — bitta oila","ru":"Три аромата — одна семья","en":"Three scents, one family","ar":"ثلاثة عطور — عائلة واحدة"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Asl dizayn: 1000 ml, 22 yuvish","ru":"Оригинальный дизайн: 1000 мл, 22 стирки","en":"Original design: 1000 ml, 22 washes","ar":"التصميم الأصلي: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Gul barglari","line":"Gulzordek yengil va tiniq","hook":"Har yuvishda — yangi uzilgan gullar.","desc":"BÄRC Gel Crystal Bloom — yengil va tiniq gulli ifor. Dog‘ va hidni ketkazadi, ranglarni yorqin saqlaydi, matoni og‘irlashtirmaydi. Sovuq suvda ham to‘liq ishlaydi.","for":"Rangli va kundalik kiyimlar uchun: ko‘ylaklar, bolalar kiyimi, yozgi yengil matolar."},"ru":{"scent":"Цветочные лепестки","line":"Лёгкий и прозрачный, как цветник","hook":"В каждой стирке — свежесрезанные цветы.","desc":"BÄRC Gel Crystal Bloom — лёгкий прозрачный цветочный аромат. Убирает пятна и запахи, сохраняет яркость цвета и не утяжеляет ткань. Работает и в холодной воде.","for":"Для цветных и повседневных вещей: рубашки, детская одежда, лёгкие летние ткани."},"en":{"scent":"Flower petals","line":"Light and clear as a flower garden","hook":"Freshly cut flowers, every wash.","desc":"BÄRC Gel Crystal Bloom is a light, clear floral scent. It removes stains and odours, keeps colours bright and never weighs fabric down. Works in cold water too.","for":"For colours and everyday clothes: shirts, kids’ clothes, light summer fabrics."},"ar":{"scent":"بتلات الزهور","line":"خفيف وصافٍ كحديقة زهور","hook":"زهور مقطوفة للتو في كل غسلة.","desc":"BÄRC Gel Crystal Bloom عطر زهري خفيف وصافٍ. يزيل البقع والروائح، ويحافظ على إشراق الألوان، ولا يثقل القماش. يعمل في الماء البارد أيضًا.","for":"للملابس الملونة واليومية: القمصان، ملابس الأطفال، الأقمشة الصيفية الخفيفة."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-original', 6, 'published', 'gel', 'Original', '#1F8040', '{"bg":"#05261A","bg2":"#01110A","surface":"#18733A","accent":"#9BE58A","glow":"#2DB352"}', 'assets/img/gel-original.webp?v=2', 'assets/img/gel-original-atmo.webp', '[{"src":"assets/img/gel-original-studio.webp","cap":{"uz":"Har tomchida — toza natija","ru":"Чистый результат в каждой капле","en":"A clean result in every drop","ar":"نتيجة نظيفة في كل قطرة"}},{"src":"assets/img/gel-room.webp","cap":{"uz":"Uchala ifor — bitta oila","ru":"Три аромата — одна семья","en":"Three scents, one family","ar":"ثلاثة عطور — عائلة واحدة"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Asl dizayn: 1000 ml, 22 yuvish","ru":"Оригинальный дизайн: 1000 мл, 22 стирки","en":"Original design: 1000 ml, 22 washes","ar":"التصميم الأصلي: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Yashil yaproqlar","line":"Klassik tozalik hidi","hook":"Toza kir hidi — gel shaklida.","desc":"BÄRC Gel Original — klassik formula, suyuq shaklda. Shudringli yaproqlardek tetik ifor va qiyin dog‘larga kuchli ta’sir. Katta oilaviy yuvish uchun qulay.","for":"Oilaviy katta yuvishlar uchun: choyshab, sochiq, ish kiyimi."},"ru":{"scent":"Зелёные листья","line":"Классический запах чистоты","hook":"Запах чистого белья — в форме геля.","desc":"BÄRC Gel Original — классическая формула в жидком виде. Бодрящий аромат листьев в росе и сильное действие на сложные пятна. Удобен для большой семейной стирки.","for":"Для больших семейных стирок: постельное, полотенца, рабочая одежда."},"en":{"scent":"Green leaves","line":"The classic smell of clean","hook":"The smell of clean laundry, as a gel.","desc":"BÄRC Gel Original is the classic formula in liquid form. A crisp scent of dewy leaves with strong action on tough stains. Made for big family washes.","for":"For big family washes: bed linen, towels, workwear."},"ar":{"scent":"أوراق خضراء","line":"رائحة النظافة الكلاسيكية","hook":"رائحة الغسيل النظيف — على شكل جل.","desc":"BÄRC Gel Original هو التركيبة الكلاسيكية في شكل سائل. عطر منعش لأوراق مبللة بالندى وتأثير قوي على البقع الصعبة. مناسب للغسيل العائلي الكبير.","for":"للغسيل العائلي الكبير: الشراشف والمناشف وملابس العمل."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('powder-ocean', 7, 'published', 'powder', 'Ocean Fresh', '#0E6FD0', '{"bg":"#04234A","bg2":"#010D1E","surface":"#0E66C2","accent":"#6FD6FF","glow":"#1C9BF0"}', 'assets/img/powder-ocean.webp?v=2', 'assets/img/powder-ocean-atmo.webp', '[{"src":"assets/img/powder-ocean-studio.webp","cap":{"uz":"10 kg — butun oila uchun kuch","ru":"10 кг силы для всей семьи","en":"10 kg of power for the whole family","ar":"10 كغ من القوة لكل العائلة"}},{"src":"assets/img/powder-room.webp","cap":{"uz":"Ocean Fresh va Purple Splash","ru":"Ocean Fresh и Purple Splash","en":"Ocean Fresh and Purple Splash","ar":"Ocean Fresh و Purple Splash"}},{"src":"assets/img/powder-photo.jpg","cap":{"uz":"Asl dizayn: Max Power 10 kg","ru":"Оригинальный дизайн: Max Power 10 кг","en":"Original design: Max Power 10 kg","ar":"التصميم الأصلي: Max Power ‏10 كغ"}}]', '{"uz":{"scent":"Dengiz shabadasi va oq gullar","line":"Dengiz shabadasidek toza","hook":"Kiyimingizda — dengiz shabadasi.","desc":"BÄRC Max Power Ocean Fresh — dengiz yangiligi va oq gullar notasi. Qiyin dog‘ va hidni ketkazadi, oq kiyimni yorqin, rangli kiyimni tiniq qiladi. 10 kg uzoq vaqtga yetadi.","for":"Katta oila va ko‘p kir uchun: choyshab, sochiq, maktab formasi, sport kiyimi."},"ru":{"scent":"Морской бриз и белые цветы","line":"Чисто, как морской бриз","hook":"На вашей одежде — морской бриз.","desc":"BÄRC Max Power Ocean Fresh — морская свежесть с нотами белых цветов. Убирает сложные пятна и запахи, белое делает ярким, цветное — насыщенным. 10 кг хватит надолго.","for":"Для большой семьи и большого количества белья: постельное, полотенца, школьная форма, спортивная одежда."},"en":{"scent":"Sea breeze and white flowers","line":"Clean as a sea breeze","hook":"A sea breeze on your clothes.","desc":"BÄRC Max Power Ocean Fresh brings ocean freshness with notes of white flowers. It removes tough stains and odours, brightens whites and keeps colours vivid. 10 kg lasts a long time.","for":"For big families and big loads: bed linen, towels, school uniforms, sportswear."},"ar":{"scent":"نسيم البحر وزهور بيضاء","line":"نظيف كنسيم البحر","hook":"نسيم البحر على ملابسك.","desc":"BÄRC Max Power Ocean Fresh انتعاش البحر مع لمسات الزهور البيضاء. يزيل البقع والروائح الصعبة، ويجعل الأبيض ناصعًا والألوان زاهية. 10 كغ تكفي لوقت طويل.","for":"للعائلات الكبيرة والغسيل الكثير: الشراشف والمناشف والزي المدرسي والملابس الرياضية."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('powder-purple', 8, 'published', 'powder', 'Purple Splash', '#9A2FC8', '{"bg":"#2A0A3D","bg2":"#110318","surface":"#8E2DBF","accent":"#E79BFF","glow":"#B847E8"}', 'assets/img/powder-purple.webp?v=2', 'assets/img/powder-purple-atmo.webp', '[{"src":"assets/img/powder-purple-studio.webp","cap":{"uz":"10 kg — butun oila uchun kuch","ru":"10 кг силы для всей семьи","en":"10 kg of power for the whole family","ar":"10 كغ من القوة لكل العائلة"}},{"src":"assets/img/powder-room.webp","cap":{"uz":"Ocean Fresh va Purple Splash","ru":"Ocean Fresh и Purple Splash","en":"Ocean Fresh and Purple Splash","ar":"Ocean Fresh و Purple Splash"}},{"src":"assets/img/powder-photo.jpg","cap":{"uz":"Asl dizayn: Max Power 10 kg","ru":"Оригинальный дизайн: Max Power 10 кг","en":"Original design: Max Power 10 kg","ar":"التصميم الأصلي: Max Power ‏10 كغ"}}]', '{"uz":{"scent":"Binafsha gullar","line":"Yorqin va quvnoq ifor","hook":"Har yuvishda — rang va kayfiyat.","desc":"BÄRC Max Power Purple Splash — yorqin gulli ifor bilan kuchli tozalash. Dog‘ va hidni ketkazadi, iforni uzoq saqlaydi. Sovuq va qisqa dasturda ham ishlaydi.","for":"Yorqin iforni yoqtiradiganlar uchun: kundalik kiyim, uy to‘qimachiligi, sport kiyimi."},"ru":{"scent":"Фиолетовые цветы","line":"Яркий и весёлый аромат","hook":"В каждой стирке — цвет и настроение.","desc":"BÄRC Max Power Purple Splash — сильная чистка с ярким цветочным ароматом. Убирает пятна и запахи, надолго сохраняет аромат. Работает и в холодной короткой стирке.","for":"Для любителей яркого аромата: повседневная одежда, домашний текстиль, спортивная форма."},"en":{"scent":"Violet flowers","line":"A bright, cheerful scent","hook":"Colour and mood in every wash.","desc":"BÄRC Max Power Purple Splash is a powerful clean with a bright floral scent. It removes stains and odours and keeps the scent for longer. Works in cold, short washes too.","for":"For lovers of a bright scent: everyday clothes, home textiles, sportswear."},"ar":{"scent":"زهور بنفسجية","line":"عطر مشرق ومبهج","hook":"لون ومزاج في كل غسلة.","desc":"BÄRC Max Power Purple Splash تنظيف قوي بعطر زهري مشرق. يزيل البقع والروائح ويحفظ العطر لفترة أطول. يعمل في الغسيل البارد والقصير أيضًا.","for":"لمحبي العطر المشرق: الملابس اليومية، المنسوجات المنزلية، الملابس الرياضية."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('oxi', 9, 'published', 'oxi', 'OXI Power', '#E9D8B4', '{"bg":"#0D1B33","bg2":"#050B16","surface":"#1E3A66","accent":"#E9C98E","glow":"#3F6FB0"}', 'assets/img/oxi.webp?v=2', 'assets/img/oxi-atmo.webp', '[{"src":"assets/img/oxi-photo-front.webp","cap":{"uz":"Asl surat: old tomoni — 15 kapsula","ru":"Оригинальное фото: лицевая сторона — 15 капсул","en":"Original photo: front — 15 pods","ar":"صورة أصلية: الواجهة — 15 كبسولة"}},{"src":"assets/img/oxi-photo-back-1.webp","cap":{"uz":"Orqa tomoni: qo‘llash yo‘riqnomasi va dozalar","ru":"Обратная сторона: инструкция и дозировка","en":"Back: instructions and dosage","ar":"الخلف: التعليمات والجرعات"}},{"src":"assets/img/oxi-photo-back-2.webp","cap":{"uz":"Orqa tomoni: qo‘llash yo‘riqnomasi va dozalar","ru":"Обратная сторона: инструкция и дозировка","en":"Back: instructions and dosage","ar":"الخلف: التعليمات والجرعات"}},{"src":"assets/img/oxi-photo-back-3.webp","cap":{"uz":"30 kapsulali qadoq — orqa tomoni","ru":"Упаковка 30 капсул — обратная сторона","en":"30-pod pack — back","ar":"عبوة 30 كبسولة — الخلف"}},{"src":"assets/img/oxi-studio.webp","cap":{"uz":"Faol kislorod — dog‘ning dushmani","ru":"Активный кислород против пятен","en":"Active oxygen versus stains","ar":"الأكسجين النشط ضد البقع"}},{"src":"assets/img/oxi-room.webp","cap":{"uz":"Oq kiyim oppoq, rangli — yorqin","ru":"Белое — белоснежное, цветное — яркое","en":"Whites whiter, colours brighter","ar":"الأبيض ناصع والألوان زاهية"}}]', '{"uz":{"scent":"Faol kislorod","line":"Dog‘ ketadi, rang qoladi","hook":"Eng qaysar dog‘ ham chekinadi.","desc":"BÄRC OXI Power — faol kislorodli dog‘ ketkazgich kapsula. Kir yuvishda kuchaytiruvchi sifatida yoki ivitib qo‘yish uchun ishlatiladi: qiyin dog‘larni ko‘taradi, oqni oqartiradi, rangni asraydi. Xlorsiz formula 60–90 °C issiq suvda eng samarali.","for":"Qiyin dog‘lar uchun: oq ko‘ylak va choyshab, bolalar kiyimi, sochiq, parda va gilam. Kiyimdan tashqari — lavabo va sirtlarni tozalashda ham."},"ru":{"scent":"Активный кислород","line":"Пятна уходят, цвет остаётся","hook":"Даже самое упрямое пятно отступит.","desc":"BÄRC OXI Power — капсула-пятновыводитель с активным кислородом. Используется как усилитель стирки или для замачивания: поднимает сложные пятна, отбеливает белое, бережёт цвет. Формула без хлора эффективнее всего в горячей воде 60–90 °C.","for":"Для сложных пятен: белые рубашки и постельное, детская одежда, полотенца, шторы и ковры. А ещё — для мойки раковин и поверхностей."},"en":{"scent":"Active oxygen","line":"Stains go, colour stays","hook":"Even the most stubborn stain backs down.","desc":"BÄRC OXI Power is an active-oxygen stain-remover pod. Use it as a wash booster or for soaking: it lifts tough stains, brightens whites and protects colour. The chlorine-free formula works best in hot water at 60–90 °C.","for":"For tough stains: white shirts and bed linen, kids’ clothes, towels, curtains and carpets. Also for cleaning sinks and surfaces."},"ar":{"scent":"أكسجين نشط","line":"البقع تزول واللون يبقى","hook":"حتى أعند البقع تتراجع.","desc":"BÄRC OXI Power كبسولة لإزالة البقع بالأكسجين النشط. تُستخدم كمعزز للغسيل أو للنقع: ترفع البقع الصعبة، وتبيّض الأبيض، وتحمي اللون. التركيبة الخالية من الكلور أكثر فعالية في الماء الساخن 60–90 °م.","for":"للبقع الصعبة: القمصان البيضاء والشراشف، ملابس الأطفال، المناشف، الستائر والسجاد. وأيضًا لتنظيف الأحواض والأسطح."}}', 1793263695368, 1793263695368);
INSERT INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('booster', 10, 'published', 'booster', 'Endless Scent', '#9B4FB5', '{"bg":"#2B0F33","bg2":"#120515","surface":"#8A3E9E","accent":"#F0B6F0","glow":"#C764D8"}', 'assets/img/booster.webp?v=2', 'assets/img/booster-atmo.webp', '[{"src":"assets/img/booster-studio.webp","cap":{"uz":"Bir qoshiq — haftalab ifor","ru":"Одна ложка — аромат на недели","en":"One scoop, weeks of freshness","ar":"مغرفة واحدة — انتعاش لأسابيع"}},{"src":"assets/img/booster-room.webp","cap":{"uz":"Choyshab va sochiq doim xushbo‘y","ru":"Постельное и полотенца всегда свежие","en":"Linen and towels that stay fresh","ar":"مفارش ومناشف تبقى منعشة"}},{"src":"assets/img/booster-photo.jpg","cap":{"uz":"6 xil ifor va 3 xil hajm","ru":"6 ароматов и 3 размера","en":"6 scents and 3 sizes","ar":"6 عطور و3 أحجام"}}]', '{"uz":{"scent":"Ametist va yana 5 ta ifor","line":"Haftalab saqlanadigan ifor","hook":"Shkafni ochsangiz ham — yangi yuvilgandek.","desc":"BÄRC Scent Booster — yuvish paytida eriydigan ifor granulalari. Kiyimga uzoq saqlanadigan yangilik beradi, dimiqqan hidlarni yo‘qotadi. 6 xil ifor: Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony va Ocean Breeze.","for":"Iforni yaxshi ko‘radiganlar uchun: kundalik kiyim, choyshab va sochiq, sport kiyimi. Har qanday kukun, gel yoki kapsula bilan birga ishlatiladi."},"ru":{"scent":"Аметист и ещё 5 ароматов","line":"Аромат, который держится неделями","hook":"Открываете шкаф — будто только что постирали.","desc":"BÄRC Scent Booster — ароматные гранулы, которые растворяются во время стирки. Дарят одежде стойкую свежесть и убирают затхлость. 6 ароматов: Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony и Ocean Breeze.","for":"Для любителей аромата: повседневная одежда, постельное и полотенца, спортивная форма. Используется вместе с любым порошком, гелем или капсулами."},"en":{"scent":"Amethyst and 5 more scents","line":"Scent that lasts for weeks","hook":"Open the wardrobe — it smells freshly washed.","desc":"BÄRC Scent Booster is scent granules that dissolve in the wash. They give clothes long-lasting freshness and remove musty smells. 6 scents: Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony and Ocean Breeze.","for":"For scent lovers: everyday clothes, bed linen and towels, sportswear. Use together with any powder, gel or pods."},"ar":{"scent":"الجمشت و5 عطور أخرى","line":"عطر يدوم لأسابيع","hook":"تفتح الخزانة — وكأنها غُسلت للتو.","desc":"BÄRC Scent Booster حبيبات عطرية تذوب أثناء الغسيل. تمنح الملابس انتعاشًا يدوم وتزيل رائحة الرطوبة. 6 عطور: Amethyst وCrystal Bloom وOriginal وRose Blush وGolden Harmony وOcean Breeze.","for":"لمحبي العطر: الملابس اليومية، الشراشف والمناشف، الملابس الرياضية. يُستخدم مع أي مسحوق أو جل أو كبسولات."}}', 1793263695368, 1793263695368);
